WITH aggregated AS (SELECT event_date_utc, ad_product_type, CASE WHEN ad_product_type IN ('sponsored_products', 'sponsored_brands') THEN 'search' WHEN ad_product_type = 'sponsored_television' THEN 'video' ELSE 'display' END AS channel_group_key, campaign_id_string, marketplace_name, SUM(impressions) AS impressions, SUM(clicks) AS clicks, SUM(spend) AS spend, currency_iso_code, COUNT(DISTINCT user_id) AS reach_users FROM sponsored_ads_traffic WHERE ad_product_type IN ('sponsored_products', 'sponsored_brands', 'sponsored_display', 'sponsored_television') GROUP BY event_date_utc, ad_product_type, CASE WHEN ad_product_type IN ('sponsored_products', 'sponsored_brands') THEN 'search' WHEN ad_product_type = 'sponsored_television' THEN 'video' ELSE 'display' END, campaign_id_string, marketplace_name, currency_iso_code) SELECT event_date_utc, ad_product_type, channel_group_key, campaign_id_string, marketplace_name, impressions, clicks, spend, currency_iso_code, reach_users, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM aggregated
